window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[260]={"id":"260","numero":260,"titre":"Hématurie","objectifs":[{"id":"260-1","rang":"A","rubrique":"Définition","titre":"Connaître la définition d'une hématurie","contenu":"<p>L'<span class=\"kw-def\"><strong>hématurie</strong></span> est la <span class=\"kw-def\">présence anormale de sang dans les urines</span>, visible ou non à l'œil nu. On distingue deux formes selon la <span class=\"kw-bio\">quantité de globules rouges</span>, sans qu'aucune ne préjuge de la gravité de la cause.</p>\n      <table >\n        <thead><tr><th>Forme</th><th>Définition &amp; seuils</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-def\"><strong>Hématurie macroscopique</strong></span></td>\n            <td><span class=\"kw-clinique\">Visible à l'œil nu</span>, à partir de <span class=\"kw-chiffre\">500 GR/µL</span> → coloration des urines <span class=\"kw-clinique\">rosée, rouge ou brunâtre</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\"><strong>Hématurie microscopique</strong></span></td>\n            <td>\n              <span class=\"kw-clinique\">Invisible à l'œil nu</span>, dépistée par <span class=\"kw-bio\">bandelette urinaire (BU)</span> :\n              <ul>\n                <li><strong>Seuil :</strong> <span class=\"kw-chiffre\">≥ 5-10 GR/mm³</span> (= <span class=\"kw-chiffre\">≥ 5-10 GR/µL</span>)</li>\n                <li><strong>Sensibilité :</strong> <span class=\"kw-chiffre\">90 %</span></li>\n                <li><strong>Faux positifs :</strong> <span class=\"kw-bio\">hémoprotéines</span> (myoglobinurie, hémoglobinurie, porphyrie)</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\"><strong>Confirmation (ECBU)</strong></span></td>\n            <td>Examen cytologique quantitatif des urines dans <strong>tous <span class=\"kw-clinique\">les</span> cas</strong> — seuil <span class=\"kw-chiffre\">≥ 10 GR/mm³</span> (soit <span class=\"kw-chiffre\">10 000 GR/mL</span>)</td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>📌 Pas de corrélation type ↔ gravité.</strong> Il n'existe <span class=\"kw-alerte\">aucune corrélation</span> entre le type d'<span class=\"kw-bio\">hématurie</span> (macro ou micro) et la gravité de la maladie causale. La démarche diagnostique est <strong>la même</strong> pour une <span class=\"kw-bio\">hématurie</span> macroscopique ou microscopique persistante.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 259 — <span class=\"kw-bio\">Protéinurie</span> - <span class=\"kw-clinique\">syndrome néphrotique</span> · 161 — <span class=\"kw-clinique\">Infection urinaire</span></em></p>","frequence":0},{"id":"260-2","rang":"B","rubrique":"Physiopathologie","titre":"Connaître les principaux mécanismes des hématuries","contenu":"<p>Deux grands mécanismes opposent <span class=\"kw-clinique\">les</span> hématuries <span class=\"kw-def\">urologiques</span> (origine <span class=\"kw-clinique\">vasculaire</span>, le long de l'arbre urinaire) et <span class=\"kw-def\">néphrologiques</span> (origine <span class=\"kw-clinique\">parenchymateuse</span>, le plus souvent glomérulaire). Cette dichotomie structure toute la démarche étiologique.</p>\n      <table >\n        <thead><tr><th>Mécanisme</th><th><span class=\"kw-bio\">Hématurie</span> urologique</th><th><span class=\"kw-bio\">Hématurie</span> néphrologique (parenchymateuse)</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-def\"><strong>Lésion</strong></span></td>\n            <td><span class=\"kw-clinique\">Lésion</span> anatomique du parenchyme ou de l'arbre urinaire mettant en communication <span class=\"kw-clinique\">les</span> vaisseaux sanguins et la lumière de la voie excrétrice (du fond d'un calice jusqu'à l'urètre)</td>\n            <td>Passage des <span class=\"kw-bio\">GR</span> à travers la <span class=\"kw-def\">membrane basale glomérulaire (MBG)</span> altérée par des lésions <span class=\"kw-etio\">congénitales</span> ou <span class=\"kw-etio\">acquises</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\"><strong>Origine du saignement</strong></span></td>\n            <td>Saignement d'origine <span class=\"kw-clinique\">vasculaire</span></td>\n            <td>Saignement d'origine <span class=\"kw-clinique\">parenchymateuse</span> (le plus souvent <span class=\"kw-clinique\">glomérulaire</span>)</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\"><strong>Caillots</strong></span></td>\n            <td>Possibles (caractère vasculaire du saignement)</td>\n            <td><span class=\"kw-alerte\">Absents</span> — action <span class=\"kw-bio\">fibrinolytique de l'urokinase tubulaire</span></td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Discriminant clé.</strong> La présence de <span class=\"kw-clinique\">caillots</span> oriente vers une origine <span class=\"kw-clinique\">urologique</span> : l'<span class=\"kw-bio\">urokinase tubulaire</span> rend l'<span class=\"kw-bio\">hématurie</span> néphrologique <span class=\"kw-clinique\">incoagulable</span>.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 261 — Néphropathie glomérulaire</em></p>","frequence":1},{"id":"260-3","rang":"A","rubrique":"Diagnostic positif","titre":"Diagnostiquer une hématurie microscopique et une hématurie macroscopique","contenu":"<p>Le <span class=\"kw-def\">diagnostic positif</span> repose sur la <span class=\"kw-bio\">BU</span> (<span class=\"kw-def\">dépistage</span>), l'<span class=\"kw-bio\">ECBU</span> (confirmation et quantification) et l'<strong>élimination des diagnostics différentiels</strong> (fausses hématuries) avant toute enquête étiologique.</p>\n      <table >\n        <thead><tr><th>Étape</th><th>Modalités</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Bandelette urinaire</strong></td>\n            <td>\n              <ul>\n                <li><strong>Seuil :</strong> <span class=\"kw-chiffre\">≥ 5-10 GR/mm³</span> · <strong>sensibilité <span class=\"kw-chiffre\">90 %</span></strong></li>\n                <li><strong>Prélèvement :</strong> urines du matin, fraîchement émises après toilette génitale, en dehors de la période menstruelle</li>\n                <li><strong>Faux positifs :</strong> <span class=\"kw-bio\">hémoprotéines</span> (myoglobinurie, hémoglobinurie, porphyrie)</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-bio\">ECBU</span> (confirmation)</strong></td>\n            <td>Seuil <span class=\"kw-chiffre\">≥ 10 GR/mm³</span> ; orientation étiologique : <span class=\"kw-bio\">cylindres hématiques</span> et <span class=\"kw-bio\">GR déformés (acanthocytes)</span> en faveur d'une origine <span class=\"kw-clinique\">glomérulaire</span></td>\n          </tr>\n          <tr>\n            <td><strong>Indications du <span class=\"kw-def\">dépistage</span> micro</strong></td>\n            <td>\n              <ul>\n                <li>Systématique (médecine du travail, médecine préventive)</li>\n                <li>Enquête étiologique : <span class=\"kw-clinique\">HTA</span>, <span class=\"kw-bio\">protéinurie</span>, <span class=\"kw-clinique\">OMI</span>, <span class=\"kw-clinique\">insuffisance rénale</span></li>\n                <li>ATCD de <span class=\"kw-etio\">néphropathie familiale</span>, <span class=\"kw-etio\">maladie systémique</span>, <span class=\"kw-etio\">tabagisme</span> actif ou ancien</li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n      <table >\n        <thead><tr><th>Fausse <span class=\"kw-bio\">hématurie</span> macroscopique (DD)</th><th>Causes</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-etio\"><strong>Hémorragie de voisinage</strong></span></td>\n            <td><span class=\"kw-clinique\">Urétrorragie</span> (saignement en dehors des mictions) ; <span class=\"kw-clinique\">hémospermie</span> ; hémorragie génitale (menstruations, méno-métrorragies)</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\"><strong>Coloration alimentaire</strong></span></td>\n            <td>Betteraves, choux rouges, mûres, myrtilles, rhubarbe ; colorant <span class=\"kw-ttt\">rhodamine B</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\"><strong>Coloration médicamenteuse</strong></span></td>\n            <td><span class=\"kw-ttt\">Rifampicine</span>, <span class=\"kw-ttt\">érythromycine</span>, <span class=\"kw-ttt\">métronidazole</span> ; <span class=\"kw-ttt\">vitamine B12</span> (hydroxocobalamine) ; <span class=\"kw-ttt\">salazopyrine</span>, <span class=\"kw-ttt\">ibuprofène</span> ; laxatifs à la phénolphtaléine ; antiseptiques (povidone-iodine, eau de Javel)</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\"><strong>Origine métabolique</strong></span></td>\n            <td><span class=\"kw-bio\">Hémoglobinurie</span> (hémolyse), <span class=\"kw-bio\">myoglobinurie</span> (rhabdomyolyse), <span class=\"kw-bio\">porphyrie</span>, urobilinurie ; intoxication plomb / mercure</td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Piège <span class=\"kw-bio\">BU</span>.</strong> La <span class=\"kw-bio\">BU</span> détecte une <span class=\"kw-bio\">activité peroxydasique</span> catalysée par <span class=\"kw-clinique\">les</span> <span class=\"kw-bio\">hémoprotéines</span> : une <span class=\"kw-bio\">BU</span> positive sans GR à l'<span class=\"kw-bio\">ECBU</span> = <span class=\"kw-alerte\">hémoglobinurie ou myoglobinurie</span>, pas une vraie <span class=\"kw-bio\">hématurie</span>.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 259 — <span class=\"kw-bio\">Protéinurie</span> - <span class=\"kw-clinique\">syndrome néphrotique</span> · 161 — <span class=\"kw-clinique\">Infection urinaire</span></em></p>","frequence":0},{"id":"260-4","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître la valeur localisatrice d'une hématurie macroscopique","contenu":"<p>La <span class=\"kw-clinique\">chronologie du saignement</span> sur le temps mictionnel a une <span class=\"kw-def\">valeur localisatrice</span> dans <span class=\"kw-clinique\">les</span> hématuries macroscopiques d'origine urologique. La couleur et l'absence de caillots orientent à l'inverse vers une cause néphrologique.</p>\n      <table >\n        <thead><tr><th>Chronologie mictionnelle</th><th>Localisation suggérée</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-clinique\"><strong>Initiale</strong></span> (début de miction)</td><td>Localisation <span class=\"kw-clinique\">urétro-cervico-prostatique</span></td></tr>\n          <tr><td><span class=\"kw-clinique\"><strong>Terminale</strong></span> (fin de miction)</td><td>Localisation <span class=\"kw-clinique\">vésicale</span>, prostatique</td></tr>\n          <tr><td><span class=\"kw-clinique\"><strong>Totale</strong></span></td><td>Peut être <span class=\"kw-clinique\">rénale</span> ; mais en cas d'hémorragie abondante, <span class=\"kw-alerte\">elle n'a pas de valeur localisatrice</span></td></tr>\n        </tbody>\n      </table>\n      <table >\n        <thead><tr><th>Caractère évocateur</th><th><span class=\"kw-bio\">Hématurie</span> néphrologique macroscopique</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Chronologie</strong></td><td><span class=\"kw-clinique\">Totale</span></td></tr>\n          <tr><td><strong>Couleur</strong></td><td><span class=\"kw-clinique\">Marron</span> (« bouillon de bœuf » ou « coca-cola »)</td></tr>\n          <tr><td><strong>Symptômes</strong></td><td><span class=\"kw-clinique\">Sans douleur</span>, sans brûlures mictionnelles</td></tr>\n          <tr><td><strong>Caillots</strong></td><td><span class=\"kw-alerte\">Sans caillot</span> — action fibrinolytique de l'<span class=\"kw-bio\">urokinase tubulaire</span></td></tr>\n          <tr><td><strong>À distance</strong></td><td>Origine glomérulaire confirmée par <span class=\"kw-bio\">hématurie microscopique</span> à la <span class=\"kw-bio\">BU</span>, souvent associée à une <span class=\"kw-bio\">protéinurie</span></td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 261 — Néphropathie glomérulaire · 310 — Tumeur prostate</em></p>","frequence":0},{"id":"260-5","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître les principaux examens complémentaires à prescrire devant une hématurie","contenu":"<p>Un <span class=\"kw-def\">bilan de première intention systématique</span> est réalisé dans <strong>tous <span class=\"kw-clinique\">les</span> cas</strong>, complété selon l'orientation <span class=\"kw-clinique\">urologique</span> ou <span class=\"kw-clinique\">néphrologique</span>. C'est l'objectif le plus tombable de l'item (<span class=\"kw-chiffre\">6 ⭐</span>).</p>\n      <table >\n        <thead><tr><th>Situation</th><th>Examens à prescrire</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-def\"><strong>Tous les cas</strong></span><br>(bilan initial)</td>\n            <td>\n              <ul>\n                <li><span class=\"kw-bio\">NFS</span></li>\n                <li><span class=\"kw-bio\">Créatininémie</span></li>\n                <li><span class=\"kw-bio\">Bilan d'hémostase</span> (<span class=\"kw-bio\">TP</span>, <span class=\"kw-bio\">TCA</span>, <span class=\"kw-bio\">fibrinogène</span>)</li>\n                <li><span class=\"kw-bio\">ECBU</span></li>\n                <li><span class=\"kw-imagerie\">Échographie des voies urinaires</span> (reins, vessie, prostate)</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-clinique\"><strong>Origine urologique suspectée</strong></span></td>\n            <td>\n              <ul>\n                <li><span class=\"kw-imagerie\">Uro-TDM</span> (ou <span class=\"kw-imagerie\">Uro-IRM</span>)</li>\n                <li><strong>2ⁿᵈ intention — <span class=\"kw-imagerie\">fibroscopie</span> urétro-vésicale :</strong> si <span class=\"kw-imagerie\">imagerie sans étiologie</span>, <span class=\"kw-bio\">cytologie urinaire positive</span>, ou <span class=\"kw-etio\">FR de tumeur urothéliale</span> ; souple en consultation sous <span class=\"kw-clinique\">anesthésie locale</span> ; biopsies au bloc sous <span class=\"kw-clinique\">AG</span></li>\n                <li><strong>Urétéroscopie</strong> (rigide ou souple, au bloc sous AG) : suspicion de tumeur de la <span class=\"kw-clinique\">voie excrétrice supérieure</span></li>\n                <li><span class=\"kw-imagerie\">Artériographie</span> (après <span class=\"kw-imagerie\">TDM</span>) : <span class=\"kw-alerte\">saignement actif sur hématurie traumatique</span></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-clinique\"><strong>Origine néphrologique suspectée</strong></span></td>\n            <td>\n              <ul>\n                <li><span class=\"kw-bio\">Protéinurie</span> (<span class=\"kw-chiffre\">24 h</span> ou échantillon), en dehors des épisodes d'<span class=\"kw-bio\">hématurie</span> macroscopique</li>\n                <li><strong><span class=\"kw-imagerie\">PBR</span> écho-guidée</strong> si : altération récente et rapide de la fonction rénale ; suspicion de <span class=\"kw-clinique\">néphropathie glomérulaire</span> (<span class=\"kw-bio\">hématurie</span> micro + <span class=\"kw-bio\">protéinurie</span>) ; <span class=\"kw-bio\">hématurie</span> macroscopique <span class=\"kw-clinique\">récidivante isolée</span> sans cause urologique (ex. néphropathie à <span class=\"kw-chiffre\">IgA</span>)</li>\n                <li><span class=\"kw-bio\">Recherche génétique</span> (syndrome d'Alport) selon le tableau et <span class=\"kw-clinique\">les</span> ATCD</li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>📌 Séquence à retenir.</strong> <span class=\"kw-bio\">Hématurie</span> macroscopique isolée → <span class=\"kw-clinique\">éliminer d'abord une cause urologique</span>. <span class=\"kw-bio\">Hématurie</span> microscopique isolée avec bilan initial négatif → rechercher en particulier une <span class=\"kw-alerte\">tumeur de l'appareil urinaire</span>. En cas de bilan négatif : <span class=\"kw-def\">surveillance</span> uronéphrologique, d'autant plus si FR de tumeur urothéliale.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 261 — Néphropathie glomérulaire · 311 — Tumeur rénale · 310 — Tumeur prostate · 264 — <span class=\"kw-ci\">Insuffisance rénale</span> chronique</em></p>","frequence":6},{"id":"260-6","rang":"B","rubrique":"Contenu multimédia","titre":"Exemples typiques de causes fréquentes d'hématurie en imagerie","contenu":"<p>L'<span class=\"kw-imagerie\">échographie des voies urinaires</span> puis l'<span class=\"kw-imagerie\">uro-TDM</span> mettent en évidence <span class=\"kw-clinique\">les</span> causes urologiques fréquentes d'<span class=\"kw-bio\">hématurie</span>. Les principales entités à reconnaître en imagerie sont rappelées ci-dessous (sémiologie détaillée renvoyée aux items dédiés).</p>\n      <table >\n        <thead><tr><th>Cause fréquente</th><th>Imagerie de 1ʳᵉ intention</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-etio\"><strong>Carcinome urothélial</strong></span> (vessie, voie excrétrice supérieure)</td><td><span class=\"kw-imagerie\">Uro-TDM</span> + <span class=\"kw-clinique\">fibroscopie / cystoscopie</span></td></tr>\n          <tr><td><span class=\"kw-etio\"><strong>Cancer du rein</strong></span></td><td><span class=\"kw-imagerie\">Échographie</span> puis <span class=\"kw-imagerie\">uro-TDM</span> (<span class=\"kw-radio\">masse rénale</span>)</td></tr>\n          <tr><td><span class=\"kw-etio\"><strong>Lithiase urinaire</strong></span></td><td><span class=\"kw-imagerie\">Uro-TDM sans injection</span> (<span class=\"kw-radio\">calcul radio-opaque</span>)</td></tr>\n          <tr><td><span class=\"kw-etio\"><strong>HBP / cancer de la prostate</strong></span></td><td><span class=\"kw-imagerie\">Échographie vésico-prostatique</span></td></tr>\n          <tr><td><span class=\"kw-etio\"><strong>Nécrose papillaire</strong></span></td><td><span class=\"kw-imagerie\">Uro-scanner</span> : <span class=\"kw-radio\">amputation calicielle</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>À enrichir (image).</strong> <span class=\"kw-clinique\">Les</span> clichés annotés des causes fréquentes (<span class=\"kw-clinique\">masse</span> rénale, tumeur de vessie, calcul, amputation calicielle) ne figurent pas dans la fiche source. Kevin pourra ajouter ces images depuis <code>IMAGERIE A CONNAITRE.pdf</code> ou les items dédiés.\n        <!-- TODO Kevin : déposer les clichés (uro-TDM masse rénale / tumeur vessie / lithiase / amputation calicielle) dans assets/images/260/ -->\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 311 — Tumeur rénale · 310 — Tumeur prostate · 265 — Lithiase urinaire</em></p>","frequence":0},{"id":"260-7","rang":"A","rubrique":"Contenu multimédia","titre":"Photographies d'un exemple typique d'hématurie macroscopique","contenu":"<p>L'<span class=\"kw-def\">hématurie macroscopique</span> est <span class=\"kw-clinique\">visible à l'œil nu</span> dès <span class=\"kw-chiffre\">500 GR/µL</span>. L'aspect des urines oriente vers l'origine du saignement.</p>\n      <table >\n        <thead><tr><th>Aspect des urines</th><th>Orientation</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-clinique\"><strong>Rosée / rouge vif</strong></span> ± caillots</td><td>Origine <span class=\"kw-clinique\">urologique</span> (saignement vasculaire récent)</td></tr>\n          <tr><td><span class=\"kw-clinique\"><strong>Brunâtre / marron</strong></span> (« bouillon de bœuf », « coca-cola »), sans caillot</td><td>Origine <span class=\"kw-clinique\">néphrologique</span> (glomérulaire)</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>Astuce de recueil.</strong> Demander au patient de <span class=\"kw-clinique\">conserver ses urines</span> permet de visualiser directement la coloration et d'éventuels <span class=\"kw-clinique\">caillots</span> (<span class=\"kw-alerte\">signe de gravité</span>, cf. obj-11).</div>\n      <div class=\"callout callout-warn\"><strong>À enrichir (photo).</strong> La photographie clinique d'urines hématuriques n'est pas disponible dans la fiche source.\n        <!-- TODO Kevin : déposer une photo d'hématurie macroscopique dans assets/images/260/ -->\n      </div>","frequence":0},{"id":"260-8","rang":"A","rubrique":"Contenu multimédia","titre":"Photographies d'une bandelette urinaire","contenu":"<p>La <span class=\"kw-bio\">bandelette urinaire (BU)</span> détecte le sang via une <span class=\"kw-bio\">activité peroxydasique</span> catalysée par <span class=\"kw-clinique\">les</span> hémoprotéines. Elle dépiste l'<span class=\"kw-bio\">hématurie</span> microscopique (<span class=\"kw-chiffre\">sensibilité 90 %</span>) mais doit toujours être confirmée par l'<span class=\"kw-bio\">ECBU</span>.</p>\n      <table >\n        <thead><tr><th>Paramètre de la <span class=\"kw-bio\">BU</span></th><th>Intérêt</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-bio\"><strong>Sang</strong></span></td><td><span class=\"kw-def\">Dépistage</span> <span class=\"kw-bio\">hématurie</span> (seuil <span class=\"kw-chiffre\">≥ 5-10 GR/mm³</span>) ; <span class=\"kw-alerte\">faux positif</span> si hémoglobinurie / myoglobinurie</td></tr>\n          <tr><td><span class=\"kw-bio\"><strong>Leucocytes · nitrites</strong></span></td><td>Orientation vers une <span class=\"kw-etio\">infection urinaire</span></td></tr>\n          <tr><td><span class=\"kw-bio\"><strong>Protéinurie</strong></span></td><td>Argument pour une origine <span class=\"kw-clinique\">glomérulaire</span> associée</td></tr>\n          <tr><td><span class=\"kw-bio\"><strong>pH · densité · glucose · corps cétoniques</strong></span></td><td>Paramètres complémentaires standards de la <span class=\"kw-bio\">BU</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>À enrichir (photo).</strong> La photographie d'une <span class=\"kw-bio\">bandelette urinaire</span> n'est pas disponible dans la fiche source.\n        <!-- TODO Kevin : déposer une photo de bandelette urinaire dans assets/images/260/ -->\n      </div>","frequence":0},{"id":"260-9","rang":"A","rubrique":"Étiologies","titre":"Connaître les principales étiologies des hématuries néphrologiques chez l'adulte et l'enfant","contenu":"<p><span class=\"kw-clinique\">Les</span> hématuries <span class=\"kw-def\">néphrologiques</span> (parenchymateuses, le plus souvent glomérulaires) se déclinent selon qu'elles sont microscopiques ou macroscopiques. <strong>Dogme :</strong> toute <span class=\"kw-bio\">hématurie</span> isolée fait d'abord évoquer une <span class=\"kw-alerte\">origine urologique</span> (tumeur de l'épithélium urinaire).</p>\n      <table >\n        <thead><tr><th>Présentation</th><th>Étiologies néphrologiques</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-def\"><strong>Hématurie microscopique</strong></span></td>\n            <td>\n              <ul>\n                <li><strong>Glomérulopathies (1ᵉʳ lieu) :</strong> <span class=\"kw-etio\">GNRP</span>, <span class=\"kw-etio\">syndrome d'Alport</span>, <span class=\"kw-etio\">néphropathie à IgA</span>, <span class=\"kw-etio\">GN membrano-proliférative</span>, <span class=\"kw-etio\">GN aiguë post-infectieuse</span></li>\n                <li><span class=\"kw-etio\">Syndrome hémolytique et urémique (SHU)</span></li>\n                <li><span class=\"kw-etio\">Néphropathie interstitielle aiguë médicamenteuse</span></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\"><strong>Hématurie macroscopique</strong></span></td>\n            <td>\n              <ul>\n                <li><span class=\"kw-etio\">Néphropathie à IgA primitive (Berger)</span> et <span class=\"kw-etio\">syndrome d'Alport</span> : <span class=\"kw-bio\">hématurie</span> macroscopique <span class=\"kw-clinique\">récidivante</span></li>\n                <li><span class=\"kw-etio\">GNRP</span> (prolifération extra-capillaire)</li>\n                <li><span class=\"kw-etio\">Polykystose rénale</span> (<span class=\"kw-alerte\">rupture</span> vasculaire intra-kystique)</li>\n                <li><span class=\"kw-etio\">Infarctus rénal</span>, <span class=\"kw-etio\">nécrose papillaire</span></li>\n                <li><span class=\"kw-etio\">Thrombose de la veine rénale</span> (<span class=\"kw-clinique\">syndrome néphrotique</span>)</li>\n                <li>Syndrome <span class=\"kw-etio\">« casse-noisette »</span> (compression de la veine rénale gauche entre aorte et artère mésentérique supérieure)</li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n      <table >\n        <thead><tr><th>Focus — <span class=\"kw-clinique\">Nécrose</span> papillaire</th><th>Détail</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Définition</strong></td><td><span class=\"kw-clinique\">Nécrose</span> <span class=\"kw-etio\">ischémique</span> ± étendue des papilles rénales</td></tr>\n          <tr><td><strong>Étiologies fréquentes</strong></td><td><span class=\"kw-etio\">Diabète</span> ; <span class=\"kw-etio\">drépanocytose</span> ; <span class=\"kw-etio\">uropathie obstructive</span> ; <span class=\"kw-etio\">néphropathies interstitielles</span> ; <span class=\"kw-etio\">néphropathie aux analgésiques</span> ; <span class=\"kw-etio\">pyélonéphrite</span></td></tr>\n          <tr><td><span class=\"kw-clinique\"><strong>Présentation</strong></span></td><td><span class=\"kw-clinique\">Colique néphrétique</span> (migration des fragments papillaires) ± <span class=\"kw-clinique\">fièvre</span>, <span class=\"kw-ci\">insuffisance rénale</span></td></tr>\n          <tr><td><strong>Confirmation</strong></td><td><span class=\"kw-imagerie\">Uro-scanner</span> : <span class=\"kw-radio\">amputation calicielle</span></td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 261 — Néphropathie glomérulaire · 259 — <span class=\"kw-bio\">Protéinurie</span> - <span class=\"kw-clinique\">syndrome néphrotique</span> · 264 — <span class=\"kw-ci\">Insuffisance rénale</span> chronique</em></p>","frequence":0},{"id":"260-10","rang":"A","rubrique":"Étiologies","titre":"Connaître les principales étiologies des hématuries urologiques chez l'adulte et l'enfant","contenu":"<p><span class=\"kw-clinique\">Les</span> hématuries <span class=\"kw-def\">urologiques</span> peuvent être micro ou macroscopiques. La <span class=\"kw-alerte\">tumeur de l'appareil urinaire</span> est la hantise à éliminer devant toute <span class=\"kw-bio\">hématurie</span> isolée ; l'<span class=\"kw-etio\">infection urinaire</span> en est la 1ʳᵉ étiologie.</p>\n      <table >\n        <thead><tr><th>Groupe</th><th>Étiologies urologiques</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-etio\"><strong>1ʳᵉ étiologie</strong></span></td>\n            <td><span class=\"kw-etio\">Infection urinaire</span> : <span class=\"kw-clinique\">cystite</span> ++ (plutôt macroscopique, <span class=\"kw-chiffre\">30 %</span>), PNA (plutôt microscopique), <span class=\"kw-clinique\">prostatite</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\"><strong>Causes fréquentes</strong></span></td>\n            <td>\n              <ul>\n                <li><span class=\"kw-etio\">Carcinome urothélial</span> (vessie, voie excrétrice supérieure)</li>\n                <li><span class=\"kw-etio\">Cancer du rein</span></li>\n                <li><span class=\"kw-etio\">Lithiase urinaire</span></li>\n                <li><span class=\"kw-etio\">HBP</span>, <span class=\"kw-etio\">cancer de la prostate</span></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\"><strong>Causes rares</strong></span></td>\n            <td>\n              <ul>\n                <li>Tumeurs bénignes du rein (<span class=\"kw-etio\">angiomyolipome</span>) ; tumeurs de la voie excrétrice supérieure</li>\n                <li><span class=\"kw-etio\">Tuberculose</span>, <span class=\"kw-etio\">bilharziose</span></li>\n                <li><span class=\"kw-clinique\">Cystite</span> <span class=\"kw-etio\">toxique</span> au <span class=\"kw-ttt\">cyclophosphamide</span></li>\n                <li>Saignement d'un kyste rénal ; <span class=\"kw-etio\">traumatisme</span> rénal ou des voies urinaires</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-clinique\"><strong>Diagnostic d'élimination</strong></span></td>\n            <td><span class=\"kw-etio\">Hématurie d'effort</span> : après activité physique prolongée, <span class=\"kw-clinique\">microscopique dans 80 %</span> ; mécanisme mixte (perméabilité glomérulaire à l'effort + microtraumatismes) ; CAT = repos puis bilan si persistance à distance de l'effort</td>\n          </tr>\n        </tbody>\n      </table>\n      <table >\n        <thead><tr><th>5 FR de <span class=\"kw-clinique\">carcinome</span> urothélial</th><th>Détail</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-etio\"><strong>Tabac</strong></span></td><td>Principal FR — multiplie le risque de tumeur de vessie <span class=\"kw-chiffre\">× 3</span></td></tr>\n          <tr><td><span class=\"kw-alerte\"><strong>Carcinogènes industriels</strong></span></td><td>Évoquer <span class=\"kw-alerte\">systématiquement une exposition professionnelle</span> (ex. activité de peintre)</td></tr>\n          <tr><td><span class=\"kw-etio\"><strong>Inflammation / irritation vésicale</strong></span></td><td><span class=\"kw-etio\">Bilharziose urinaire</span> (<span class=\"kw-clinique\">carcinome</span> épidermoïde) ; <span class=\"kw-etio\">sondage vésical chronique</span> ; <span class=\"kw-etio\">irradiation pelvienne</span> ; <span class=\"kw-ttt\">cyclophosphamide</span></td></tr>\n          <tr><td><span class=\"kw-etio\"><strong>ATCD de tumeur urinaire</strong></span></td><td>Tumeur du bas ou du haut appareil urinaire</td></tr>\n          <tr><td><span class=\"kw-etio\"><strong>Syndrome de Lynch</strong></span></td><td>Prédisposition <span class=\"kw-etio\">héréditaire</span> (tumeurs de la voie excrétrice supérieure)</td></tr>\n        </tbody>\n      </table>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/260/carcinogenes-professionnels-peintre.png\" alt=\"Illustration de l'exposition professionnelle aux carcinogènes industriels (activité de peintre) comme facteur de risque de carcinome urothélial de vessie\" loading=\"lazy\">\n        <figcaption>Exposition professionnelle aux <span class=\"kw-alerte\">carcinogènes industriels</span> (illustration : activité de peintre) — à évoquer systématiquement devant une tumeur de vessie. Source : fiche source EDN item 260 — <span class=\"kw-bio\">Hématurie</span>.</figcaption>\n      </figure>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 311 — Tumeur rénale · 310 — Tumeur prostate · 161 — <span class=\"kw-clinique\">Infection urinaire</span> · 265 — Lithiase urinaire</em></p>","frequence":2},{"id":"260-11","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître l'arbre diagnostique des hématuries","contenu":"<p>La démarche diagnostique cherche à trancher <span class=\"kw-clinique\">urologique</span> <span class=\"kw-bio\">vs</span> <span class=\"kw-clinique\">néphrologique</span> par l'interrogatoire, l'examen clinique et le bilan paraclinique gradué (objectif très tombable, <span class=\"kw-chiffre\">5 ⭐</span>).</p>\n      <table >\n        <thead><tr><th>Argument</th><th>Origine urologique</th><th>Origine néphrologique</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-def\"><strong>Hématurie macroscopique</strong></span></td>\n            <td><span class=\"kw-clinique\">Initiale / terminale / totale</span> ; ± douleurs, <span class=\"kw-clinique\">caillots</span>, brûlures mictionnelles ; cyclique (endométriose)</td>\n            <td><span class=\"kw-clinique\">Totale</span>, marron (« bouillon de bœuf »), <span class=\"kw-clinique\">sans douleur ni caillot</span></td>\n          </tr>\n          <tr>\n            <td><strong>Signes associés</strong></td>\n            <td><span class=\"kw-clinique\">SFU</span> (bas appareil), douleurs lombaires chroniques, <span class=\"kw-clinique\">coliques néphrétiques</span></td>\n            <td><span class=\"kw-clinique\">Asthénie</span>, perte de poids, <span class=\"kw-clinique\">fièvre</span>, <span class=\"kw-clinique\">HTA</span> (<span class=\"kw-clinique\">céphalées</span>, acouphènes), <span class=\"kw-clinique\">OMI</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-bio\"><strong>ECBU / cytologie</strong></span></td>\n            <td><span class=\"kw-bio\">Cellules tumorales de haut grade</span> (bonne sensibilité)</td>\n            <td><span class=\"kw-bio\">Cylindres hématiques</span>, <span class=\"kw-bio\">acanthocytes</span> (GR déformés)</td>\n          </tr>\n        </tbody>\n      </table>\n      <table >\n        <thead><tr><th>Examen clinique — recherche orientée</th><th>Signification</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Palpation des fosses lombaires</strong></td><td><span class=\"kw-def\">Contact</span> lombaire → <span class=\"kw-etio\">tumeur</span> ou <span class=\"kw-etio\">polykystose</span></td></tr>\n          <tr><td><strong>Percussion lombaire douloureuse</strong></td><td>Colique néphrétique (lithiase ou caillotage de la voie excrétrice)</td></tr>\n          <tr><td><span class=\"kw-clinique\"><strong>Varicocèle</strong></span></td><td>Compression veineuse → <span class=\"kw-etio\">tumeur rénale gauche</span></td></tr>\n          <tr><td><strong>Touchers pelviens</strong></td><td>Hypertrophie / cancer prostatique, <span class=\"kw-clinique\">masse</span> pelvienne</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>📌 Arbre décisionnel.</strong> Tous <span class=\"kw-clinique\">les</span> cas : <span class=\"kw-bio\">NFS, créatinine, hémostase, ECBU</span> + <span class=\"kw-imagerie\">échographie</span>. Puis selon orientation : <span class=\"kw-imagerie\">uro-TDM</span> ± cytologie ± cystoscopie (urologique) ou <span class=\"kw-bio\">protéinurie</span> ± <span class=\"kw-imagerie\">PBR</span> (néphrologique). <span class=\"kw-bio\">Hématurie</span> isolée à bilan négatif → <span class=\"kw-alerte\">éliminer une tumeur urinaire</span> en priorité.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 259 — <span class=\"kw-bio\">Protéinurie</span> - <span class=\"kw-clinique\">syndrome néphrotique</span> · 261 — Néphropathie glomérulaire · 311 — Tumeur rénale</em></p>","frequence":5},{"id":"260-12","rang":"A","rubrique":"Identifier une urgence","titre":"Savoir identifier une hématurie macroscopique caillotante et ses signes de gravité","contenu":"<p><span class=\"kw-clinique\">Les</span> <span class=\"kw-alerte\">situations d'urgence</span> concernent l'<span class=\"kw-bio\">hématurie</span> <span class=\"kw-clinique\">macroscopique</span> : la <span class=\"kw-alerte\">déglobulisation aiguë</span> et le <span class=\"kw-alerte\">caillotage</span> vésical ou de la voie excrétrice.</p>\n      <table >\n        <thead><tr><th>Élément</th><th>Détail</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Risque du caillotage</strong></td><td><span class=\"kw-alerte\">Rétention aiguë d'urine (RAU)</span> et <span class=\"kw-alerte\">IRA obstructive</span> (blocage par accumulation des caillots)</td></tr>\n          <tr>\n            <td><span class=\"kw-clinique\"><strong>Présentations cliniques</strong></span></td>\n            <td>\n              <ul>\n                <li><span class=\"kw-clinique\">Visualisation directe des caillots</span> (demander au patient de garder ses urines)</li>\n                <li><span class=\"kw-clinique\">Dysurie</span>, globe vésical (blocage vésical)</li>\n                <li><span class=\"kw-clinique\">Douleurs lombaires</span> (caillotage de la voie excrétrice supérieure)</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-alerte\">Signes de gravité</span> à rechercher</strong></td>\n            <td>\n              <ul>\n                <li><span class=\"kw-alerte\">Retentissement hémodynamique</span> (<span class=\"kw-bio\">hématurie</span> macroscopique)</li>\n                <li>Signes d'<span class=\"kw-alerte\">anémie aiguë ou chronique</span></li>\n                <li>Signes d'<span class=\"kw-alerte\">HTA maligne</span> (néphropathie glomérulaire sévère)</li>\n                <li><span class=\"kw-alerte\">Globe vésical</span> (RAU sur caillotage)</li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\"><strong><span class=\"kw-alerte\">Urgence</span>.</strong> Une <span class=\"kw-bio\">hématurie</span> macroscopique <span class=\"kw-clinique\">caillotante</span> avec <span class=\"kw-alerte\">globe vésical</span> impose une prise en charge immédiate (cf. obj-12) : la <span class=\"kw-alerte\">déglobulisation</span> et l'<span class=\"kw-alerte\">IRA obstructive</span> en font le <span class=\"kw-def\">pronostic</span>.</div>","frequence":0},{"id":"260-13","rang":"B","rubrique":"Prise en charge","titre":"Connaître les éléments de prise en charge d'une hématurie caillotante","contenu":"<p>La prise en charge d'une <span class=\"kw-bio\">hématurie</span> <span class=\"kw-clinique\">caillotante</span> dépend du <span class=\"kw-clinique\">niveau</span> du caillotage (bas appareil <span class=\"kw-bio\">vs</span> voie excrétrice supérieure) et vise à lever l'obstacle et surveiller la déglobulisation.</p>\n      <table >\n        <thead><tr><th>Niveau</th><th>Prise en charge</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-clinique\"><strong>Caillotage bas</strong></span><br>(vésical ± RAU)</td>\n            <td>\n              <ol>\n                <li><span class=\"kw-ttt\">Sonde vésicale double courant</span> + <span class=\"kw-bio\">ECBU</span> à la pose</li>\n                <li><span class=\"kw-clinique\">Décaillotage manuel</span> à la seringue</li>\n                <li><span class=\"kw-ttt\">Irrigation vésicale en continu</span>, débit adapté à la couleur des urines</li>\n                <li><span class=\"kw-clinique\">Surveillance des volumes d'entrée / sortie</span></li>\n              </ol>\n            </td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-clinique\"><strong>Caillotage haut</strong></span><br>(voie excrétrice supérieure)</td>\n            <td>\n              <ul>\n                <li><span class=\"kw-ttt\">Drainage</span> des cavités rénales par <span class=\"kw-ttt\">sonde JJ ou sonde urétérale</span> : peut être proposé</li>\n                <li><span class=\"kw-ttt\">Décaillotage endoscopique au bloc opératoire</span> : parfois nécessaire</li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\"><strong>⚠️ <span class=\"kw-ci\">Contre-indication</span> absolue.</strong> Le <span class=\"kw-ci\">cathéter sus-pubien est contre-indiqué</span> en cas d'<span class=\"kw-bio\">hématurie</span> macroscopique (risque de dissémination d'une éventuelle <span class=\"kw-clinique\">lésion</span> <span class=\"kw-etio\">tumorale</span>).</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 161 — <span class=\"kw-clinique\">Infection urinaire</span> · 265 — Lithiase urinaire</em></p>","frequence":0}],"astuces":[],"strategie":{"urgence":"<p><strong>Déglobulisation aiguë <span class=\"q\">— saignement actif</span></strong></p><p>rechercher un <span class=\"kw-alerte\">retentissement hémodynamique</span> et une <span class=\"kw-alerte\">anémie aiguë</span></p><ul><li>Toute <span class=\"kw-clinique\">hématurie macroscopique</span> abondante = situation de <span class=\"kw-alerte\">saignement actif</span></li></ul><p><strong>Caillotage <span class=\"q\">— vésical ou voie excrétrice</span></strong></p><p>lever l'obstacle sans délai — <span class=\"kw-ttt\">drainage</span> / décaillotage (cf. 💊 Principes de PEC)</p><ul><li>Risque de <span class=\"kw-alerte\">rétention aiguë d'urine (RAU)</span> par blocage vésical</li><li>Risque d'<span class=\"kw-alerte\">IRA obstructive</span> par accumulation des caillots</li></ul>","redflags":"<ul><li><span class=\"kw-alerte\">Retentissement hémodynamique</span> — <span class=\"kw-bio\">hématurie</span> macroscopique abondante</li><li><span class=\"kw-alerte\">Anémie aiguë ou chronique</span></li><li><span class=\"kw-alerte\">HTA maligne</span> — néphropathie glomérulaire sévère</li><li><span class=\"kw-alerte\">Globe vésical</span> — RAU sur caillotage</li><li><span class=\"kw-bio\">Hématurie</span> macroscopique <span class=\"kw-alerte\">caillotante</span> (caillots visibles — demander au patient de conserver ses urines)</li></ul>","principes":"<p>La PEC d'une <span class=\"kw-bio\">hématurie</span> <span class=\"kw-clinique\">caillotante</span> dépend du <span class=\"kw-clinique\">niveau du caillotage</span> (bas appareil <span class=\"kw-bio\">vs</span> voie excrétrice supérieure) : lever l'obstacle et surveiller la <span class=\"kw-alerte\">déglobulisation</span>.</p><p><strong>Caillotage bas <span class=\"q\">— vésical ± RAU</span></strong></p><p><span class=\"kw-ci\">Cathéter sus-pubien contre-indiqué</span> en cas d'<span class=\"kw-bio\">hématurie</span> macroscopique (risque de dissémination d'une <span class=\"kw-clinique\">lésion</span> <span class=\"kw-etio\">tumorale</span>)</p><ul><li><span class=\"kw-ttt\">Sonde vésicale double courant</span> + <span class=\"kw-bio\">ECBU</span> à la pose</li><li><span class=\"kw-ttt\">Décaillotage manuel à la seringue</span></li><li><span class=\"kw-ttt\">Irrigation vésicale en continu</span>, débit adapté à la couleur des urines</li><li><span class=\"kw-clinique\">Surveillance des volumes d'entrée / sortie</span></li></ul><p><strong>Caillotage haut <span class=\"q\">— voie excrétrice supérieure</span></strong></p><ul><li><span class=\"kw-ttt\">Drainage</span> des cavités rénales par <span class=\"kw-ttt\">sonde JJ ou sonde urétérale</span> : peut être proposé</li><li><span class=\"kw-ttt\">Décaillotage endoscopique au bloc opératoire</span> : parfois nécessaire</li></ul>","suivi":"<p><strong>Bilan initial négatif</strong></p><p>objectif : ne pas méconnaître une <span class=\"kw-alerte\">tumeur de l'appareil urinaire</span></p><ul><li><span class=\"kw-clinique\">Surveillance simple uronéphrologique</span> (rythme et principes non clairement définis dans <span class=\"kw-clinique\">les</span> recommandations)</li><li>D'autant plus recommandée s'il existe un <span class=\"kw-etio\">FR de tumeur urothéliale</span></li></ul><p><strong><span class=\"kw-bio\">Hématurie</span> d'effort <span class=\"q\">— diagnostic d'élimination</span></strong></p><ul><li><span class=\"kw-clinique\">Réévaluation après quelques jours de repos</span></li><li>Si <span class=\"kw-clinique\">persistance à distance de l'effort</span> → <span class=\"kw-bio\">bilan</span> pour ne pas méconnaître une cause organique</li></ul>"},"liensGlobaux":[{"href":"https://manuel4.cuen.fr/spip.php?rubrique9","label":"Collège CUEN — Hématurie"},{"href":"https://www.urofrance.org/lafu-academie/formation-du-college/referentiel-du-college-durologie-6eme-edition/chapitre-13-item-260-hematurie/","label":"Collège d'Urologie (6e éd.) — Chap. 13 · Item 260 Hématurie"}],"cards":[]};